fn get_min_val(a: &Vec<i8>) -> i8 {
    *a.iter().min().unwrap()
}

fn get_max_val(a: &Vec<i8>) -> i8 {
    *a.iter().max().unwrap()
}

fn nanquantile(a: Vec<i8>, q: i8) -> i8 {
    assert!(q >= 0 && q <= 100, "Quantile percentage must be between 0 and 100");

    let min_val = get_min_val(&a);
    let max_val = get_max_val(&a);

    if q == 0 {
        return min_val;
    } else if q == 100 {
        return max_val;
    }

    // Sort the array to find the quantile
    let mut sorted_a = a.clone();
    sorted_a.sort();

    // Calculate the index for the quantile
    let index = ((q as f64 / 100.0) * (sorted_a.len() as f64 - 1.0)).round() as usize;

    // Return the value at the calculated index
    sorted_a[index]
}

fn main() {
    let data = vec![3, 1, 4, 1, 5, 9, 2, 6];
    let quantile_0 = nanquantile(data.clone(), 0);
    let quantile_100 = nanquantile(data.clone(), 100);
    let quantile_50 = nanquantile(data.clone(), 50);

    println!("Min: {}", quantile_0);   // Should print the minimum value
    println!("Max: {}", quantile_100);  // Should print the maximum value
    println!("50th Percentile: {}", quantile_50); // Should print the median
}